$stmt=$conn->prepare("SELECT transaction_id,quantity,container_size,delivery_status,status,created_at FROM transactions WHERE user_id=? AND transaction_id NOT LIKE 'RWD-%' AND (status='pending' OR (status='approved' AND LOWER(COALESCE(delivery_status,'pending'))<>'delivered')) ORDER BY created_at DESC LIMIT 1");$stmt->bind_param('s',$userId);$stmt->execute();$active=$stmt->get_result()->fetch_assoc();
$stmt=$conn->prepare("SELECT COUNT(*) total,SUM(status='approved' AND LOWER(COALESCE(delivery_status,''))='delivered') completed FROM transactions WHERE user_id=? AND transaction_id NOT LIKE 'RWD-%'");$stmt->bind_param('s',$userId);$stmt->execute();$counts=$stmt->get_result()->fetch_assoc()?:[];
