<script>
(()=>{const limit=15*60*1000,warningAt=60*1000;let expires=Date.now()+limit,timer=null,countdown=null,lastPing=0;const box=document.getElementById('idleWarning'),count=document.getElementById('idleCountdown'),form=document.getElementById('customerAutoLogout'),token=form.querySelector('[name=csrf_token]').value;function submit(){if(form&&!form.dataset.sent){form.dataset.sent='1';form.submit()}}function schedule(){clearTimeout(timer);clearInterval(countdown);box.classList.remove('show');timer=setTimeout(warn,Math.max(0,expires-Date.now()-warningAt))}function warn(){box.classList.add('show');update();countdown=setInterval(update,1000)}function update(){const left=Math.max(0,Math.ceil((expires-Date.now())/1000));count.textContent=left;if(left<=0){clearInterval(countdown);submit()}}function keepAlive(){const now=Date.now();if(now-lastPing<60000)return;lastPing=now;fetch('auto_logout.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({csrf_token:token,action:'keepalive'}),credentials:'same-origin'}).then(r=>{if(r.status===401)submit()}).catch(()=>{})}function reset(){expires=Date.now()+limit;schedule();keepAlive()}['pointerdown','keydown','scroll','touchstart'].forEach(name=>addEventListener(name,reset,{passive:true}));document.getElementById('staySignedIn').addEventListener('click',reset);document.getElementById('logoutNow').addEventListener('click',submit);document.addEventListener('visibilitychange',()=>{if(!document.hidden){if(Date.now()>=expires)submit();else{reset()}}});schedule()})();
</script></body></html>
